+  color-scheme:dark;
+}
+
+*{box-sizing:border-box}
+html{background:var(--mc-bg);scrollbar-color:#233950 #07101c}
+body{
+  margin:0;
+  background:var(--mc-bg);
+  color:var(--mc-text);
+  font:14px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;
+  -webkit-font-smoothing:antialiased;
+}
+
+a{color:inherit}
+
+.mc-shell{
+  min-height:100vh;
+  display:grid;
+  grid-template-columns:var(--mc-sidebar) minmax(0,1fr);
+  background:
+    radial-gradient(circle at 78% -12%,rgba(33,94,176,.17) 0,transparent 30%),
+    radial-gradient(circle at 50% 120%,rgba(27,86,151,.08) 0,transparent 38%),
+    linear-gradient(180deg,#030914 0%,#06101d 100%);
+}
+
+.mc-sidebar{
+  position:sticky;
+  top:0;
+  height:100vh;
+  overflow:auto;
+  display:flex;
+  flex-direction:column;
+  padding:18px 14px 14px;
+  border-right:1px solid #12253b;
+  background:linear-gradient(180deg,rgba(3,10,19,.99),rgba(4,12,23,.985));
+  box-shadow:12px 0 44px rgba(0,0,0,.18);
+  scrollbar-width:thin;
+}
+
+.mc-brand{
+  display:flex;
+  align-items:center;
+  gap:12px;
+  min-height:60px;
+  padding:4px 12px 18px;
+  color:var(--mc-text);
+  text-decoration:none;
+}
+
+.mc-brand-mark{
+  display:grid;
+  place-items:center;
+  width:39px;
+  height:39px;
+  flex:0 0 39px;
+  border:1px solid #275f9e;
+  border-radius:12px;
+  background:linear-gradient(145deg,#0f3763,#071b31);
+  box-shadow:0 0 24px rgba(47,140,255,.16);
+}
+.mc-brand-mark img{display:block;width:24px;height:24px;filter:drop-shadow(0 0 6px rgba(70,166,255,.35))}
+.mc-brand strong,.mc-brand small{display:block}
+.mc-brand strong{font-size:14px;line-height:1.2;letter-spacing:.01em}
+.mc-brand small{margin-top:2px;color:#91a0b5;font-size:10px;text-transform:uppercase;letter-spacing:.09em}
+
+.mc-sidebar nav{flex:1}
+.mc-nav-group{margin:0 0 17px}
+.mc-nav-group h2{
+  margin:0 11px 6px;
+  color:#61738d;
+  font-size:9px;
+  font-weight:700;
+  letter-spacing:.14em;
+  text-transform:uppercase;
+}
+.mc-nav-group a{
+  display:flex;
+  align-items:center;
+  gap:9px;
+  min-height:34px;
+  margin:1px 0;
+  padding:7px 10px;
+  border:1px solid transparent;
+  border-radius:8px;
+  color:#bdc8d7;
+  text-decoration:none;
+  transition:background-color .15s ease,border-color .15s ease,color .15s ease,transform .15s ease;
+}
+.mc-nav-group a:hover{background:#0b1a2b;border-color:#17314c;color:#fff;transform:translateX(1px)}
+.mc-nav-group a.is-active{
+  color:#fff;
+  border-color:#1c5ba0;
+  background:linear-gradient(90deg,rgba(25,102,198,.76),rgba(17,68,133,.65));
+  box-shadow:inset 0 1px rgba(255,255,255,.04),0 5px 20px rgba(13,73,148,.18);
+}
+.mc-nav-icon{
+  display:grid;
+  place-items:center;
+  width:18px;
+  height:18px;
+  flex:0 0 18px;
+  color:#7f91aa;
+  font-size:12px;
+  line-height:1;
+}
+.mc-nav-group a.is-active .mc-nav-icon,.mc-nav-group a:hover .mc-nav-icon{color:#a9d6ff}
+
+.mc-sidebar-footer{
+  display:flex;
+  align-items:center;
+  gap:10px;
+  margin:5px -14px -14px;
+  padding:15px 16px;
+  border-top:1px solid #11263b;
+  background:rgba(3,10,19,.8);
+}
+.mc-sidebar-footer strong,.mc-sidebar-footer small{display:block}
+.mc-sidebar-footer strong{font-size:11px}
+.mc-sidebar-footer small{color:var(--mc-muted);font-size:10px}
+.mc-operator-avatar{
+  display:grid;
+  place-items:center;
+  width:32px;
+  height:32px;
+  border-radius:50%;
+  background:linear-gradient(145deg,#1780f1,#18509c);
+  color:#fff;
+  font-size:10px;
+  font-weight:800;
+  box-shadow:0 0 18px rgba(47,140,255,.22);
+}
+
+.mc-workspace{min-width:0}
+.mc-topbar{
+  position:sticky;
+  top:0;
+  z-index:8;
+  display:flex;
+  justify-content:space-between;
+  gap:24px;
+  align-items:flex-end;
+  padding:25px 34px 20px;
+  border-bottom:1px solid #18304b;
+  background:rgba(3,9,20,.88);
+  backdrop-filter:blur(18px);
+  box-shadow:0 9px 28px rgba(0,0,0,.09);
+}
+.mc-kicker{margin:0 0 5px;color:#4eb4ff;font-size:10px;font-weight:750;letter-spacing:.14em;text-transform:uppercase}
+.mc-topbar h1{margin:0;font-size:clamp(27px,3vw,37px);font-weight:750;letter-spacing:-.035em;line-height:1.08}
+.mc-subtitle{margin:7px 0 0;color:#93a1b4;font-size:13px}
+.mc-topbar-meta{display:flex;align-items:center;gap:12px;flex-wrap:wrap;justify-content:flex-end}
+.mc-updated{color:#8795a8;font-size:11px;white-space:nowrap}
+.mc-icon-button{
+  display:grid;
+  place-items:center;
+  width:38px;
+  height:38px;
+  border:1px solid #1a3552;
+  border-radius:10px;
+  background:#06111e;
+  color:#cfe7ff;
+  text-decoration:none;
+  font-size:17px;
+  transition:border-color .15s ease,background .15s ease,transform .15s ease;
+}
+.mc-icon-button:hover{border-color:#326ca7;background:#0a1a2b;transform:translateY(-1px)}
+
+.mc-main{max-width:1600px;margin:0 auto;padding:24px 34px 48px}
+
+.mc-grid{
+  display:grid;
+  grid-template-columns:repeat(auto-fit,minmax(205px,1fr));
+  gap:13px;
+}
+.mc-grid>*{min-width:0}
+.mc-grid>.mc-metric,.mc-grid>.mc-card-link{grid-column:auto}
+#mission-content>.mc-grid:first-child{grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:13px}
+
+.mc-card-link{display:block;min-width:0;color:inherit;text-decoration:none}
+.mc-card-link>.mc-metric{height:100%}
+
+.mc-metric,.mc-panel,.mc-unavailable{
+  border:1px solid var(--mc-border);
+  background:
+    linear-gradient(145deg,rgba(10,24,41,.97),rgba(5,15,27,.98));
+  box-shadow:0 16px 40px rgba(0,0,0,.14),inset 0 1px rgba(255,255,255,.016);
+}
+
+.mc-metric{
+  position:relative;
+  min-height:184px;
+  overflow:hidden;
+  padding:15px 15px 18px;
+  border-radius:13px;
+  transition:border-color .15s ease,transform .15s ease,box-shadow .15s ease;
+}
+.mc-card-link:hover>.mc-metric{
+  border-color:#2b6097;
+  transform:translateY(-2px);
+  box-shadow:0 19px 42px rgba(0,0,0,.2),0 0 0 1px rgba(63,154,255,.035);
