+  min-height: 100vh;
+  display: grid;
+  grid-template-columns: 235px 1fr;
+}
+
+aside {
+  border-right: 1px solid #1c2a3b;
+  background: rgba(6, 14, 26, .95);
+  padding: 24px 16px;
+  display: flex;
+  flex-direction: column;
